# Writes state\machine.md: the facts about THIS PC that the agent is given at the start of every session (the second instruction file).
# Regenerated by start.ps1 each time, so it is never stale. Small on purpose: the agent has a short context.
. "$PSScriptRoot\common.ps1"
Initialize-Contained
$m = Get-Model
$gpu = Get-GpuInfo
$afxr = Find-AirFrameXR
$L = New-Object System.Collections.Generic.List[string]
$L.Add('# This PC (generated ' + (Get-Date -Format 'yyyy-MM-dd HH:mm') + ' by scripts\probe.ps1, do not edit)')
$L.Add('')
$os = Get-CimInstance Win32_OperatingSystem
$L.Add("- Windows: $($os.Caption) build $($os.BuildNumber)")
if ($gpu) {
    $L.Add(("- GPU: {0}, {1:N1} GB VRAM, driver {2}. This agent's model ({3}) is budgeted at {4} GB of it: while it runs, a game cannot use that memory." -f $gpu.Name, ($gpu.TotalMB / 1024), $gpu.Driver, $m.displayName, $m.targetVramGB))
}
$L.Add("- Agent folder (this repo): $($script:Root)")
$L.Add("- Docs for AirFrameXR (copies of the project docs, read these first): $($script:Root)\docs-cache  (index: $($script:Root)\agent\docs-index.md)")
$L.Add("- Playbooks (already loaded for you; reread a part when unsure): $($script:Root)\agent\playbook\")
$L.Add("- Scratch folder (yours: write drafts and intermediate results here without asking, files older than 7 days are removed for you): $($script:Scratch)")
$L.Add("- You may edit only config\airframexr.json and config\user_fov_profiles.json (every change is archived automatically in $($script:Root)\history and listed in notes\auto-journal.md; a file that stops being valid JSON is reverted at once). config\session.json, config\games*, logs\ and bin\ are READ-ONLY.")
$L.Add("- Change journal (you write it, you read it at session start): $($script:Root)\notes\changes.md")
$f = Join-Path $script:RT 'cache\docs_fetched.txt'
if (Test-Path $f) { $L.Add('- Docs copied on: ' + (Get-Content -Raw $f).Trim() + ' (they describe the main branch; the installed build may be older, check the release notes when a key from the docs is missing)') }
$L.Add('')
if ($afxr) {
    $L.Add("- AirFrameXR folder: $afxr")
    foreach ($rel in 'config\airframexr.json','config\session.base.json','config\session.json','config\games.json','logs\AirFrameXR.log') {
        $p = Join-Path $afxr $rel
        if (Test-Path $p) { $i = Get-Item $p; $L.Add(("  - {0}: {1:N0} KB, last written {2}" -f $rel, ($i.Length / 1KB), $i.LastWriteTime.ToString('yyyy-MM-dd HH:mm'))) }
        else { $L.Add("  - ${rel}: not present") }
    }
    $g = Join-Path $afxr 'config\games'
    if (Test-Path $g) { $L.Add('  - per-game files: ' + ((Get-ChildItem $g -Filter *.json | ForEach-Object { $_.Name }) -join ', ')) }
    $dbg = Join-Path $afxr 'logs\debug'
    if (Test-Path $dbg) { $d = Get-ChildItem $dbg -Directory | Sort-Object Name | Select-Object -Last 1; if ($d) { $L.Add("  - newest debug run folder: logs\debug\$($d.Name)") } }
    $log = Join-Path $afxr 'logs\AirFrameXR.log'
    if (Test-Path $log) {
        $runs = Get-Content $log -Tail 20000 | Select-String -SimpleMatch 'game run recorded' | Select-Object -Last 5
        if ($runs) {
            $L.Add('')
            $L.Add('Last recorded game runs (from logs\AirFrameXR.log):')
            foreach ($r in $runs) { $L.Add('  ' + $r.Line.Trim()) }
        }
    }
} else {
    $L.Add('- AirFrameXR folder: NOT FOUND. Ask the user for it, or tell them to run install.bat -AirFrameXRDir <folder>. Without it you can only answer from the docs.')
}
$enc = New-Object System.Text.UTF8Encoding $false
[IO.File]::WriteAllText((Join-Path $script:StateDir 'machine.md'), (($L -join "`r`n") + "`r`n"), $enc)
Write-Host "state\machine.md written ($($L.Count) lines)"
